'use client';
import { useState } from 'react';
const links = ['Home', 'About', 'Menu', 'Gallery', 'Marriage Hall', 'Contact'];
const target = (label: string) => label === 'Home' ? 'home' : label === 'Marriage Hall' ? 'hall' : label.toLowerCase();
export function Brand() { return <a href="#home" className="leading-none"><span className="block text-[15px] font-bold tracking-[.24em] text-white">KEBABISH</span><span className="mt-1 block text-[8px] tracking-[.23em] text-saffron">GRILL · FAMILY RESTAURANT</span></a>; }
export function Navbar() { const [open, setOpen] = useState(false); return <header className="absolute inset-x-0 top-0 z-30 border-b border-white/15 bg-coal/10 backdrop-blur-[2px]"><div className="mx-auto flex h-[78px] max-w-[1440px] items-center justify-between px-6 lg:px-14"><Brand /><button className="grid h-10 w-10 place-content-center gap-1.5 md:hidden" aria-label="Toggle menu" onClick={() => setOpen(!open)}><i className="h-px w-6 bg-white"/><i className="h-px w-6 bg-white"/></button><nav className={`${open ? 'flex' : 'hidden'} absolute left-0 top-[78px] w-full flex-col gap-5 border-b border-white/10 bg-coal px-6 py-7 md:static md:flex md:w-auto md:flex-row md:items-center md:border-0 md:bg-transparent md:p-0 md:gap-7`}>{links.map(link => <a onClick={() => setOpen(false)} className="text-[11px] text-cream transition hover:text-saffron" href={`#${target(link)}`} key={link}>{link}</a>)}<a href="#contact" className="border border-saffron px-5 py-3 text-center text-[10px] font-bold uppercase tracking-[.16em] text-saffron transition hover:bg-saffron hover:text-coal">Book Now</a></nav></div></header>; }
